#include <cstdint>
#include <limits>
#include <optional>

std::optional<int> to_int_checked(std::int64_t v) {
    if (v < std::numeric_limits<int>::min() || v > std::numeric_limits<int>::max())
        return std::nullopt;                       // doesn't fit: refuse.
    return static_cast<int>(v);                    // explicit, and now safe.
}

int main() {
    int total = 7, count = 2;
    double avg = static_cast<double>(total) / count;   // 3.5: divide in double.
    int pct = (total * 100) / count;                   // 350: grouping explicit.

    std::int64_t product = std::int64_t{60000} * 60000; // widen BEFORE multiplying.
    auto small = to_int_checked(product);              // nullopt: too big for int.
    // int bad{product};    error: narrowing.
    return small.has_value() ? 1 : 0;
}
```

| Risk | Repair |
|---|---|
| int division. | cast one operand to double first. |
| unclear grouping. | parentheses. |
| narrowing. | brace init, or check then static_cast. |
| signed overflow. | widen before the operation, or check limits. |

